-- pintopets_vet_visits: tenant-scoped rows behind /vet-visits (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_vet_visits (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            visit_on DATE NOT NULL,
            practice VARCHAR(255),
            vet_name VARCHAR(255),
            reason VARCHAR(255) NOT NULL,
            outcome TEXT,
            cost_pence INTEGER,
            follow_up_on DATE,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_vet_visits_cost_pence_range CHECK (cost_pence BETWEEN 0 AND 100000000)
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_vet_visits_namespace ON pintopets_vet_visits (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_vet_visits_pet ON pintopets_vet_visits (namespace_id, pet_uuid)")
end
